-- ImportOpsDB -> MariaDB (esquemas SQL Server convertidos a prefijos: fin__..., cfg__..., etc.)
-- ADVERTENCIA: ejecutar SOLO en base MariaDB nueva/vacía. No ejecutar sobre una base con datos.
-- El script conserva IDs explícitos, registros y referencias; no migra archivos binarios externos.
-- Revisar el informe de compatibilidad antes de usar en producción.
CREATE DATABASE IF NOT EXISTS `ImportOpsDB` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `ImportOpsDB`;
SET NAMES utf8mb4;
SET SESSION sql_mode='NO_BACKSLASH_ESCAPES';
SET FOREIGN_KEY_CHECKS=0;
CREATE TABLE `fin__CUSTOMS_TAX_ITEM` (
  `customs_tax_item_id` BIGINT NOT NULL AUTO_INCREMENT,
  `company_id` BIGINT NOT NULL,
  `operation_id` BIGINT NOT NULL,
  `tax_code` VARCHAR(30) NOT NULL,
  `description` VARCHAR(250) NOT NULL,
  `document_reference` VARCHAR(100) NULL,
  `assessed_at` DATETIME(0) NULL,
  `amount_pen` DECIMAL(19, 2) NOT NULL,
  `notes` VARCHAR(1000) NULL,
  `is_void` TINYINT(1) NOT NULL,
  `void_reason` VARCHAR(500) NULL,
  `created_at` DATETIME(0) NOT NULL,
  `created_by` BIGINT NOT NULL,
  `modified_at` DATETIME(0) NULL,
  `modified_by` BIGINT NULL,
  `row_ver` BINARY(8) DEFAULT 0x0000000000000000 NOT NULL,
  `payer_type` VARCHAR(20) NOT NULL,
  `payment_date` DATE NULL,
  PRIMARY KEY (`customs_tax_item_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `fin__CUSTOMS_TAX_PAYMENT` (
  `customs_tax_payment_id` BIGINT NOT NULL AUTO_INCREMENT,
  `company_id` BIGINT NOT NULL,
  `operation_id` BIGINT NOT NULL,
  `customs_tax_item_id` BIGINT NOT NULL,
  `payment_date` DATETIME(0) NOT NULL,
  `amount_pen` DECIMAL(19, 2) NOT NULL,
  `payer_type` VARCHAR(20) NOT NULL,
  `payment_reference` VARCHAR(100) NULL,
  `notes` VARCHAR(1000) NULL,
  `is_void` TINYINT(1) NOT NULL,
  `void_reason` VARCHAR(500) NULL,
  `created_at` DATETIME(0) NOT NULL,
  `created_by` BIGINT NOT NULL,
  `row_ver` BINARY(8) DEFAULT 0x0000000000000000 NOT NULL,
  `funding_source` VARCHAR(20) NOT NULL,
  PRIMARY KEY (`customs_tax_payment_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

