USE `ImportOpsDB`;
CREATE OR REPLACE VIEW `fin__V_CUSTOMS_TAX_BALANCE` AS
SELECT t.company_id,t.operation_id,t.customs_tax_item_id,t.tax_code,t.description,t.amount_pen,
COALESCE(SUM(CASE WHEN p.is_void=0 THEN p.amount_pen ELSE 0 END),0) AS paid_pen,
t.amount_pen-COALESCE(SUM(CASE WHEN p.is_void=0 THEN p.amount_pen ELSE 0 END),0) AS outstanding_pen
FROM `fin__CUSTOMS_TAX_ITEM` t LEFT JOIN `fin__CUSTOMS_TAX_PAYMENT` p ON p.customs_tax_item_id=t.customs_tax_item_id
WHERE t.is_void=0
GROUP BY t.company_id,t.operation_id,t.customs_tax_item_id,t.tax_code,t.description,t.amount_pen;

CREATE OR REPLACE VIEW `fin__VW_OPERATION_FINANCIAL_SUMMARY` AS
SELECT o.operation_id,o.company_id,o.operation_no,o.client_id,
COALESCE(f.total_client_funds,0) total_client_funds,COALESCE(e.total_expenses,0) total_expenses,COALESCE(ep.total_expense_payments,0) total_expense_payments,
COALESCE(s.total_services,0) total_services,COALESCE(c.total_collections,0) total_collections,COALESCE(r.total_refunds,0) total_refunds,
COALESCE(f.total_client_funds,0)-COALESCE(ep.company_paid_expenses,0)-COALESCE(r.total_refunds,0) managed_fund_balance,
GREATEST(COALESCE(s.total_services,0)-COALESCE(c.service_collections,0),0) pending_service_collection
FROM `ops__IMPORT_OPERATION` o
LEFT JOIN (SELECT operation_id,SUM(COALESCE(base_amount,received_amount)) total_client_funds FROM `fin__CLIENT_FUND` WHERE is_deleted=0 AND fund_status IN('PARTIAL','RECEIVED','APPLIED','SETTLED') GROUP BY operation_id) f ON f.operation_id=o.operation_id
LEFT JOIN (SELECT operation_id,SUM(base_amount) total_expenses FROM `fin__OPERATION_EXPENSE` WHERE is_deleted=0 AND expense_status<>'CANCELLED' GROUP BY operation_id) e ON e.operation_id=o.operation_id
LEFT JOIN (SELECT ex.operation_id,SUM(p.base_amount) total_expense_payments,SUM(CASE WHEN p.payer_type='COMPANY' THEN p.base_amount ELSE 0 END) company_paid_expenses FROM `fin__EXPENSE_PAYMENT` p JOIN `fin__OPERATION_EXPENSE` ex ON ex.operation_expense_id=p.operation_expense_id WHERE p.is_void=0 GROUP BY ex.operation_id) ep ON ep.operation_id=o.operation_id
LEFT JOIN (SELECT operation_id,SUM(base_amount) total_services FROM `fin__OPERATION_SERVICE` WHERE is_deleted=0 AND service_status<>'CANCELLED' GROUP BY operation_id) s ON s.operation_id=o.operation_id
LEFT JOIN (SELECT operation_id,SUM(base_amount) total_collections,SUM(CASE WHEN collection_type='SERVICE' THEN base_amount ELSE 0 END) service_collections FROM `fin__CLIENT_COLLECTION` WHERE is_void=0 AND collection_status<>'VOID' GROUP BY operation_id) c ON c.operation_id=o.operation_id
LEFT JOIN (SELECT operation_id,SUM(base_amount) total_refunds FROM `fin__CLIENT_REFUND` WHERE refund_status='COMPLETED' GROUP BY operation_id) r ON r.operation_id=o.operation_id
WHERE o.is_deleted=0;
